/*
Theme Name: Careful Shopper Field Guide
Template: twentytwentyfive
Version: 3.0.0
Description: Version 2. Same words and the same disclosure rules as Version 1, in a freer field-guide design: serif display type, a netting motif, a sticky contents rail and specimen cards.
Text Domain: careful-shopper-field-guide
*/

/* ---------- Tokens ---------- */
:root {
	--fg-ink: #14231C;
	--fg-pine: #173D2D;
	--fg-pine-2: #1F4D39;
	--fg-moss: #2F6B4F;
	--fg-paper: #F7F3EA;
	--fg-paper-2: #EFE7D6;
	--fg-card: #FFFDF8;
	--fg-mist: #E3EEE7;
	--fg-amber: #F0B44C;
	--fg-amber-soft: #FCEFD6;
	--fg-amber-deep: #A8701A;
	--fg-clay: #B5531C;
	--fg-clay-dark: #8F3F13;
	--fg-white: #FFFFFF;
	--fg-line: rgba(20, 35, 28, 0.14);
	--fg-line-light: rgba(255, 255, 255, 0.18);
	--fg-display: "Fraunces", "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
	--fg-text: "Atkinson Hyperlegible", "Segoe UI", system-ui, -apple-system, Roboto, Arial, sans-serif;
	--fg-radius: 1.25rem;
	--fg-shadow: 0 0.0625rem 0 rgba(20, 35, 28, 0.06), 0 1rem 2.5rem -1.5rem rgba(20, 35, 28, 0.35);
	--fg-net: repeating-linear-gradient(45deg, transparent 0 0.6rem, rgba(255, 255, 255, 0.07) 0.6rem 0.66rem),
	          repeating-linear-gradient(-45deg, transparent 0 0.6rem, rgba(255, 255, 255, 0.07) 0.6rem 0.66rem);
	--fg-net-dark: repeating-linear-gradient(45deg, transparent 0 0.55rem, rgba(47, 107, 79, 0.16) 0.55rem 0.6rem),
	               repeating-linear-gradient(-45deg, transparent 0 0.55rem, rgba(47, 107, 79, 0.16) 0.55rem 0.6rem);
}

html { font-size: 100%; scroll-padding-top: 6rem; }
body {
	margin: 0;
	background-color: var(--fg-paper);
	color: var(--fg-ink);
	font-family: var(--fg-text);
	font-size: 1rem;
	line-height: 1.65;
	letter-spacing: 0;
	-webkit-text-size-adjust: 100%;
}
.fg, .fg *, .fg *::before, .fg *::after { box-sizing: border-box; }
.wp-site-blocks { padding: 0; }
.wp-site-blocks > *, .fg-main > *, .fg-main .wp-block-post-content > * { margin-block: 0; }
.fg h1, .fg h2, .fg h3, .fg p, .fg ul, .fg ol, .fg dl, .fg dd, .fg figure, .fg table { margin: 0; }
.fg h1, .fg h2, .fg h3 { font-family: var(--fg-display); color: inherit; letter-spacing: -0.01em; font-weight: 600; }
.fg p + p { margin-top: 1rem; }
.fg ul, .fg ol { padding: 0; list-style: none; }
.fg img { display: block; max-width: 100%; height: auto; }
.fg a { color: var(--fg-moss); text-decoration-thickness: 0.08em; text-underline-offset: 0.2em; }
.fg a:hover { color: var(--fg-ink); }
.fg strong, .fg b { font-weight: 700; }
.fg a:focus-visible, .fg button:focus-visible, .fg [tabindex]:focus-visible, .fg summary:focus-visible {
	outline: 0.1875rem solid var(--fg-clay);
	outline-offset: 0.1875rem;
	border-radius: 0.25rem;
}

/* ---------- Header ---------- */
.fg-site-header {
	position: sticky;
	top: 0;
	z-index: 50;
	background-color: rgba(247, 243, 234, 0.92);
	-webkit-backdrop-filter: saturate(1.4) blur(0.75rem);
	backdrop-filter: saturate(1.4) blur(0.75rem);
	border-bottom: 0.0625rem solid var(--fg-line);
}
.fg-header { position: relative; }
.fg-skip {
	position: absolute; left: 1rem; top: -4rem; z-index: 60;
	padding: 0.75rem 1rem; border-radius: 0.5rem;
	background: var(--fg-ink); color: var(--fg-white) !important; font-weight: 700;
}
.fg-skip:focus { top: 0.5rem; }
.fg-header__bar {
	max-width: 80rem; margin-inline: auto;
	padding: 0.75rem clamp(1rem, 4vw, 2.5rem);
	display: flex; align-items: center; justify-content: space-between; gap: 1.5rem;
}
.fg .fg-brand { display: inline-flex; align-items: center; gap: 0.75rem; text-decoration: none; color: var(--fg-ink); }
.fg-mark { flex: none; width: 2.75rem; height: 2.75rem; }
.fg-brand__text { display: flex; flex-direction: column; line-height: 1.15; }
.fg-brand__name { font-family: var(--fg-display); font-size: 1.35rem; font-weight: 700; letter-spacing: -0.01em; }
.fg-brand__tag { font-size: 0.85rem; color: var(--fg-moss); }
.fg-nav ul { display: flex; flex-wrap: wrap; gap: 0.25rem; }
.fg .fg-nav a, .fg .fg-menu a {
	display: inline-flex; align-items: center; min-height: 2.75rem;
	padding: 0.25rem 0.875rem; border-radius: 999px;
	color: var(--fg-ink); font-weight: 700; font-size: 0.95rem; text-decoration: none;
}
.fg .fg-nav a:hover { background: var(--fg-paper-2); }
.fg .fg-nav a[aria-current="page"], .fg .fg-menu a[aria-current="page"] { background: var(--fg-pine); color: var(--fg-white); }
.fg-menu-button {
	display: none; align-items: center; gap: 0.625rem;
	min-height: 3rem; padding: 0.5rem 1.125rem;
	border: 0; border-radius: 999px; cursor: pointer;
	background: var(--fg-pine); color: var(--fg-white);
	font: 700 1rem/1 var(--fg-text);
}
.fg-menu-button__bars, .fg-menu-button__bars::before, .fg-menu-button__bars::after {
	display: block; width: 1.125rem; height: 0.125rem; border-radius: 1rem; background: currentColor; content: "";
}
.fg-menu-button__bars { position: relative; }
.fg-menu-button__bars::before { position: absolute; top: -0.375rem; }
.fg-menu-button__bars::after { position: absolute; top: 0.375rem; }
.fg-menu-button[aria-expanded="true"] .fg-menu-button__bars { background: transparent; }
.fg-menu-button[aria-expanded="true"] .fg-menu-button__bars::before { top: 0; transform: rotate(45deg); }
.fg-menu-button[aria-expanded="true"] .fg-menu-button__bars::after { top: 0; transform: rotate(-45deg); }
.fg-menu { display: none; }
.fg-menu ul { display: grid; gap: 0.5rem; padding: 0.5rem clamp(1rem, 4vw, 2.5rem) 1.25rem; }
.fg .fg-menu a { width: 100%; min-height: 3rem; padding-inline: 1rem; background: var(--fg-card); border: 0.0625rem solid var(--fg-line); border-radius: 0.875rem; }

/* ---------- Page grid: hero full width, contents rail beside the guide ---------- */
.fg-main .wp-block-post-content {
	display: grid;
	grid-template-columns: [full-start] minmax(1rem, 1fr) [main-start] minmax(0, 46rem) [main-end] minmax(1rem, 1fr) [full-end];
	row-gap: clamp(2.5rem, 6vw, 4.5rem);
	padding-bottom: clamp(3rem, 8vw, 6rem);
}
.fg-main .wp-block-post-content > * { grid-column: main; min-width: 0; }
.fg-main .wp-block-post-content > .fg-hero { grid-column: full; }
.fg-main .wp-block-post-content > .fg-toc { margin-top: calc(-1 * clamp(1rem, 3vw, 2.5rem)); }

/* ---------- Hero ---------- */
.fg-hero {
	position: relative;
	overflow: hidden;
	background-color: var(--fg-pine);
	background-image: radial-gradient(60rem 30rem at 85% 10%, rgba(240, 180, 76, 0.16), transparent 60%), var(--fg-net);
	color: var(--fg-white);
}
.fg-hero__inner {
	max-width: 80rem; margin-inline: auto;
	padding: clamp(2.5rem, 7vw, 5.5rem) clamp(1rem, 4vw, 2.5rem) clamp(3rem, 8vw, 6rem);
	display: grid; grid-template-columns: minmax(0, 1fr); gap: 2.5rem; align-items: center;
}
.fg-crumbs ol { display: flex; flex-wrap: wrap; gap: 0.25rem 0.5rem; font-size: 0.9rem; margin-bottom: 1.5rem; }
.fg-crumbs li { display: inline-flex; align-items: center; gap: 0.5rem; color: rgba(255, 255, 255, 0.86); }
.fg-crumbs li + li::before { content: "/"; color: var(--fg-amber); }
.fg .fg-crumbs a { color: var(--fg-white); font-weight: 700; }
.fg-crumbs [aria-current] { color: var(--fg-amber); font-weight: 700; }
.fg-hero h1 {
	max-width: 22ch;
	font-size: clamp(1.75rem, 1.15rem + 2.6vw, 2.4rem);
	line-height: 1.12;
	font-weight: 700;
	text-wrap: balance;
}
.fg-byline { display: flex; align-items: center; gap: 0.75rem; margin-top: 1.25rem !important; font-weight: 700; }
.fg-answer {
	margin-top: 1.75rem;
	max-width: 38rem;
	padding: 1.25rem 1.5rem;
	border-radius: var(--fg-radius);
	background: rgba(255, 255, 255, 0.08);
	border: 0.0625rem solid var(--fg-line-light);
	border-left: 0.375rem solid var(--fg-amber);
	font-size: 1.05rem;
}
.fg-monogram {
	display: inline-grid; place-items: center; flex: none;
	width: 3.5rem; height: 3.5rem; border-radius: 50%;
	background: var(--fg-amber); color: var(--fg-pine);
	font: 700 1.1rem/1 var(--fg-display);
}
.fg-monogram--small { width: 2.25rem; height: 2.25rem; font-size: 0.85rem; }
.fg-hero__art { display: none; }
.fg-rings { position: relative; width: min(100%, 24rem); aspect-ratio: 1; margin-inline: auto; }
.fg-ring {
	position: absolute; inset: 0; margin: auto; border-radius: 50%;
	border: 0.0625rem dashed rgba(255, 255, 255, 0.35);
}
.fg-ring b {
	position: absolute; top: -0.875rem; left: 50%; transform: translateX(-50%);
	padding: 0.125rem 0.75rem; border-radius: 999px;
	background: var(--fg-pine-2); border: 0.0625rem solid var(--fg-line-light);
	font-size: 0.85rem; letter-spacing: 0.08em; text-transform: uppercase; white-space: nowrap;
}
.fg-ring--1 { width: 56%; height: 56%; border: 0.125rem solid var(--fg-amber); }
.fg-ring--1 b { background: var(--fg-amber); color: var(--fg-pine); border-color: var(--fg-amber); }
.fg-ring--2 { width: 78%; height: 78%; }
.fg-ring--3 { width: 100%; height: 100%; }
.fg-hero__shield { position: absolute; inset: 0; margin: auto; width: 30%; height: 30%; filter: drop-shadow(0 1rem 1.5rem rgba(0, 0, 0, 0.3)); }
.fg-hero--short .fg-answer p + p { margin-top: 1.25rem; }

/* ---------- Contents rail ---------- */
.fg-toc__box {
	border-radius: var(--fg-radius);
	background: var(--fg-card);
	border: 0.0625rem solid var(--fg-line);
	box-shadow: var(--fg-shadow);
}
.fg-toc__title {
	display: flex; align-items: center; justify-content: space-between; gap: 1rem;
	min-height: 3rem; padding: 0.75rem 1.25rem; cursor: pointer; list-style: none;
	font-family: var(--fg-display); font-size: 1.1rem; font-weight: 700;
}
.fg-toc__title::-webkit-details-marker { display: none; }
.fg-toc__title::after { content: "+"; font: 700 1.4rem/1 var(--fg-text); color: var(--fg-clay); }
.fg-toc__box[open] .fg-toc__title::after { content: "\2212"; }
.fg-toc ol { padding: 0 0.75rem 0.75rem; display: grid; gap: 0.25rem; }
.fg.fg-toc a {
	display: grid; grid-template-columns: 2rem 1fr; gap: 0.5rem; align-items: baseline;
	padding: 0.5rem 0.625rem; border-radius: 0.75rem;
	color: var(--fg-ink); text-decoration: none; font-size: 0.95rem; line-height: 1.4;
}
.fg.fg-toc a:hover { background: var(--fg-mist); }
.fg.fg-toc a.is-active { background: var(--fg-pine); color: var(--fg-white); }
.fg.fg-toc a.is-active .fg-toc__num { color: var(--fg-amber); }
.fg-toc__num { font-family: var(--fg-display); font-weight: 700; color: var(--fg-clay); }

/* ---------- Disclosure ---------- */
.fg-disclosure {
	position: relative;
	display: grid;
	grid-template-columns: 2rem minmax(0, 1fr);
	column-gap: 1rem;
	row-gap: 0.25rem;
	padding: 1.25rem 1.5rem;
	border-radius: var(--fg-radius);
	background: var(--fg-amber-soft);
	border: 0.0625rem solid rgba(168, 112, 26, 0.35);
	color: var(--fg-ink);
}
.fg-disclosure::before {
	content: "i";
	grid-row: 1 / span 2;
	display: grid; place-items: center; width: 2rem; height: 2rem; border-radius: 50%;
	background: var(--fg-amber-deep); color: var(--fg-white);
	font: 700 1.1rem/1 var(--fg-display);
}
.fg .fg-disclosure__label { align-self: center; font-size: 0.85rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: #7A4F0E; }
.fg .fg-disclosure__text { margin-top: 0; font-size: 1.1rem; line-height: 1.55; }

/* ---------- Section heads ---------- */
.fg-head { display: grid; grid-template-columns: auto 1fr; gap: 1rem; align-items: start; margin-bottom: 1.75rem; }
.fg-head__num {
	display: grid; place-items: center; width: 3rem; height: 3rem; border-radius: 0.875rem;
	background: var(--fg-pine); color: var(--fg-amber);
	font: 700 1.1rem/1 var(--fg-display);
}
.fg-head h2 { font-size: clamp(1.4rem, 1.1rem + 1.2vw, 1.85rem); line-height: 1.2; padding-top: 0.25rem; text-wrap: balance; }

/* ---------- 01 Why ---------- */
.fg-why__grid { display: grid; gap: 1.5rem; }
.fg-plate { position: relative; max-width: 28rem; }
.fg-plate::before {
	content: ""; position: absolute; inset: 0.75rem -0.75rem -0.75rem 0.75rem;
	border-radius: 1.75rem; background-color: var(--fg-mist); background-image: var(--fg-net-dark);
}
.fg-plate img { position: relative; width: 100%; aspect-ratio: 4 / 3; object-fit: cover; object-position: 42% 45%; border-radius: 1.75rem; }
.fg-plate figcaption {
	position: relative; display: inline-block; margin: 1.25rem 0 0;
	font-size: 0.85rem; color: var(--fg-ink);
}
.fg-prose { font-size: 1.05rem; max-width: 40rem; }
.fg-risk {
	margin-top: 2.5rem; padding: clamp(1.25rem, 4vw, 2rem);
	border-radius: var(--fg-radius);
	background: var(--fg-card); border: 0.0625rem solid var(--fg-line); box-shadow: var(--fg-shadow);
}
.fg-risk__title { font-size: clamp(1.2rem, 1rem + 0.8vw, 1.45rem); line-height: 1.25; margin-bottom: 0.75rem !important; color: var(--fg-clay-dark); }

/* ---------- 02 Layers ---------- */
.fg-steps { display: grid; gap: 1rem; counter-reset: none; }
.fg-step {
	position: relative;
	padding: 1.25rem 1.25rem 1.25rem 4.5rem;
	border-radius: var(--fg-radius);
	background: var(--fg-card); border: 0.0625rem solid var(--fg-line);
}
.fg-step__dot {
	position: absolute; left: 1.25rem; top: 1.25rem;
	display: grid; place-items: center; width: 2.25rem; height: 2.25rem; border-radius: 50%;
	background: var(--fg-mist); color: var(--fg-pine); font: 700 1rem/1 var(--fg-display);
}
.fg-step h3 { font-size: 1.2rem; line-height: 1.3; margin-bottom: 0.375rem !important; }
.fg-step.is-here { background-color: var(--fg-pine); background-image: var(--fg-net); color: var(--fg-white); border-color: var(--fg-pine); }
.fg-step.is-here .fg-step__dot { background: var(--fg-amber); }
.fg .fg-step__here {
	display: inline-block; margin-top: 0.75rem;
	padding: 0.125rem 0.75rem; border-radius: 999px;
	background: var(--fg-amber); color: var(--fg-pine); font-weight: 700; font-size: 0.9rem;
}
.fg-layers__close { margin-top: 1.5rem !important; font-size: 1.05rem; font-family: var(--fg-display); font-weight: 600; line-height: 1.45; color: var(--fg-pine); }

/* ---------- 03 Compare ---------- */
.fg-table { border-radius: var(--fg-radius); background: var(--fg-card); border: 0.0625rem solid var(--fg-line); box-shadow: var(--fg-shadow); overflow: hidden; }
.fg-table table { width: 100%; border-collapse: collapse; font-size: 0.95rem; }
.fg-table th, .fg-table td { padding: 0.875rem 1rem; text-align: left; vertical-align: top; }
.fg-table thead th { background: var(--fg-pine); color: var(--fg-white); font-weight: 700; font-family: var(--fg-text); }
.fg-table tbody th { font-weight: 700; color: var(--fg-pine); }
.fg-table tbody tr + tr { border-top: 0.0625rem solid var(--fg-line); }
.fg-table tbody tr:nth-child(even) { background: rgba(227, 238, 231, 0.55); }

/* ---------- 04 and 05 Products ---------- */
.fg-shop__intro { font-size: 1.05rem; max-width: 42rem; margin-bottom: 1.5rem !important; }
.fg-shop__layout { display: grid; gap: 1.5rem; }
.fg-cards, .fg-pairs { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 15.5rem), 1fr)); gap: 1.25rem; }
.fg-card {
	display: flex; flex-direction: column;
	border-radius: var(--fg-radius); overflow: hidden;
	background: var(--fg-card); border: 0.0625rem solid var(--fg-line); box-shadow: var(--fg-shadow);
}
.fg .fg-window {
	position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0.625rem;
	aspect-ratio: 16 / 10;
	background-color: var(--fg-mist); background-image: var(--fg-net-dark);
	color: var(--fg-pine); text-decoration: none;
	border-bottom: 0.0625rem solid var(--fg-line);
}
.fg-window__no {
	position: absolute; left: 0.75rem; top: 0.75rem;
	padding: 0.125rem 0.625rem; border-radius: 999px;
	background: var(--fg-pine); color: var(--fg-amber); font: 700 0.85rem/1.6 var(--fg-display);
}
.fg-window__label {
	padding: 0.375rem 0.875rem; border-radius: 999px;
	background: rgba(255, 253, 248, 0.92); border: 0.0625rem dashed var(--fg-moss);
	font-size: 0.9rem; font-weight: 700;
}
.fg-card__body { display: flex; flex-direction: column; flex: 1; padding: 1.25rem; }
.fg .fg-tag { font-size: 0.85rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--fg-moss); }
.fg-card h3 { margin: 0.25rem 0 0.875rem !important; font-size: 1.2rem; line-height: 1.25; }
.fg-facts { display: grid; gap: 0.625rem; margin-bottom: 1.25rem !important; font-size: 0.95rem; line-height: 1.5; }
.fg-facts dt { font-weight: 700; font-size: 0.85rem; letter-spacing: 0.04em; text-transform: uppercase; color: var(--fg-clay-dark); }
.fg .fg-button {
	display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem;
	min-height: 3rem; margin-top: auto; padding: 0.75rem 1.25rem;
	border-radius: 999px; background: var(--fg-clay); color: var(--fg-white);
	font-weight: 700; text-decoration: none; text-align: center;
}
.fg .fg-button:hover { background: var(--fg-clay-dark); color: var(--fg-white); }
.fg .fg-button--light { background: var(--fg-amber); color: var(--fg-pine); }
.fg .fg-button--light:hover { background: var(--fg-white); color: var(--fg-pine); }
.fg-button__arrow { font-size: 1.1rem; line-height: 1; }
.fg-pairs__groups { display: grid; gap: 2rem; }
.fg .fg-pairs__layer {
	display: flex; align-items: center; gap: 0.75rem; margin-bottom: 1rem;
	font-family: var(--fg-display); font-size: 1.2rem; font-weight: 700; color: var(--fg-pine);
}
.fg-pairs__layer::after { content: ""; flex: 1; height: 0.0625rem; background: var(--fg-line); }
.fg-shop--pairs .fg-tag { display: none; }

/* ---------- Footer ---------- */
.fg-footer { background-color: var(--fg-ink); background-image: var(--fg-net); color: var(--fg-white); }
.fg-footer__inner {
	max-width: 80rem; margin-inline: auto;
	padding: clamp(3rem, 8vw, 5rem) clamp(1rem, 4vw, 2.5rem) 2rem;
	display: grid; gap: 2rem;
}
.fg-footer__curator { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 1.25rem; align-items: start; max-width: 46rem; }
.fg-footer h2 { font-size: clamp(1.4rem, 1.1rem + 1.2vw, 1.85rem); line-height: 1.2; margin-bottom: 0.75rem !important; }
.fg-footer p { color: rgba(255, 255, 255, 0.9); }
.fg.fg-footer a { color: var(--fg-white); font-weight: 700; }
.fg.fg-footer a:hover { color: var(--fg-amber); }
.fg .fg-footer__pledge {
	justify-self: start; padding: 0.75rem 1.25rem; border-radius: 999px;
	border: 0.0625rem solid var(--fg-amber); color: var(--fg-amber); font-weight: 700;
}
.fg-footer__nav ul { display: flex; flex-wrap: wrap; gap: 0.5rem 1.5rem; }
.fg .fg-footer__nav a { display: inline-flex; align-items: center; min-height: 2.75rem; }
.fg .fg-footer__copy { padding-top: 1.5rem; border-top: 0.0625rem solid var(--fg-line-light); font-size: 0.9rem; }

/* ---------- Line illustrations (drawn for this guide; decorative) ---------- */
.fg-window__art { width: 3.75rem; height: 3.75rem; color: var(--fg-pine); }
.fg .fg-window:hover .fg-window__art { color: var(--fg-clay); }
.fg-step__art { position: absolute; right: 1.25rem; top: 1.25rem; width: 2.75rem; height: 2.75rem; color: var(--fg-moss); }
.fg-step.is-here .fg-step__art { color: var(--fg-amber); }
.fg-risk { position: relative; }
.fg-risk__art { float: right; width: 4.5rem; height: 4.5rem; margin: -0.25rem 0 0.5rem 1rem; color: var(--fg-clay); }

/* ---------- The closing disclosure: centered, with more room ---------- */
.fg-disclosure--closing {
	grid-template-columns: minmax(0, 1fr);
	justify-items: center;
	row-gap: 0.625rem;
	padding: 2rem clamp(1.25rem, 4vw, 2.5rem);
	text-align: center;
}
.fg-disclosure--closing::before { grid-row: auto; width: 2.5rem; height: 2.5rem; font-size: 1.3rem; }
.fg-disclosure--closing .fg-disclosure__text { max-width: 36rem; }

/* ---------- Motion, only for people who have not asked for less ---------- */
@media (prefers-reduced-motion: no-preference) {
	html { scroll-behavior: smooth; }
	.fg-card { transition: transform 0.2s ease, box-shadow 0.2s ease; }
	.fg-card:hover { transform: translateY(-0.25rem); box-shadow: 0 1.5rem 3rem -1.5rem rgba(20, 35, 28, 0.45); }
	.fg .fg-button, .fg .fg-nav a, .fg.fg-toc a { transition: background-color 0.15s ease, color 0.15s ease; }
	.fg-button__arrow { transition: transform 0.15s ease; }
	.fg-button:hover .fg-button__arrow { transform: translate(0.125rem, -0.125rem); }
	.fg-menu-button__bars::before, .fg-menu-button__bars::after { transition: transform 0.2s ease, top 0.2s ease; }
}

/* ---------- Small screens ---------- */
@media (max-width: 71.99rem) {
	.fg-nav { display: none; }
	.fg-menu-button { display: inline-flex; }
	.fg-menu.is-open { display: block; }
}
@media (max-width: 30rem) {
	.fg-brand__tag { display: none; }
	.fg-brand__name { font-size: 1.2rem; }
	.fg-disclosure { padding: 1.25rem; row-gap: 0.75rem; }
	.fg-disclosure::before { grid-row: 1; }
	.fg-disclosure .fg-disclosure__text { grid-column: 1 / -1; font-size: 1.05rem; }
	.fg-disclosure--closing { padding: 1.75rem 1.25rem; }
	.fg-step { padding-left: 1.25rem; padding-top: 4rem; }
	.fg-plate::before { inset: 0.5rem -0.5rem -0.5rem 0.5rem; }
	.fg-footer__curator { grid-template-columns: minmax(0, 1fr); }
	/* The comparison table becomes one card per barrier, so nothing scrolls sideways. */
	.fg-table { background: transparent; border: 0; box-shadow: none; overflow: visible; }
	.fg-table table, .fg-table tbody, .fg-table tr, .fg-table th, .fg-table td { display: block; width: 100%; }
	.fg-table thead { position: absolute; width: 0.0625rem; height: 0.0625rem; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
	.fg-table tbody { display: grid; gap: 0.75rem; }
	.fg-table tbody tr, .fg-table tbody tr:nth-child(even) {
		border: 0.0625rem solid var(--fg-line); border-radius: var(--fg-radius);
		background: var(--fg-card); box-shadow: var(--fg-shadow); overflow: hidden;
	}
	.fg-table tbody tr + tr { border-top: 0.0625rem solid var(--fg-line); }
	.fg-table tbody th { background: var(--fg-pine); color: var(--fg-white); font-family: var(--fg-display); font-size: 1.1rem; }
	.fg-table tbody td { display: grid; grid-template-columns: 6rem minmax(0, 1fr); gap: 0.75rem; padding: 0.625rem 1rem; }
	.fg-table tbody td + td { border-top: 0.0625rem solid var(--fg-line); }
	.fg-table tbody td::before { content: attr(data-label); font-weight: 700; font-size: 0.85rem; letter-spacing: 0.04em; text-transform: uppercase; color: var(--fg-clay-dark); }
}

/* ---------- Wider screens ---------- */
@media (min-width: 40rem) {
	.fg-why__grid { grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr); gap: 2.5rem; align-items: start; }
	.fg-pairs .fg-card { flex-direction: row; }
	.fg-pairs .fg-window { flex: 0 0 38%; aspect-ratio: auto; min-height: 100%; border-bottom: 0; border-right: 0.0625rem solid var(--fg-line); }
	.fg-pairs .fg-window__label { font-size: 0.85rem; }
	.fg-pairs .fg-window { padding: 2.5rem 0.75rem 1rem; }
	.fg-pairs { grid-template-columns: repeat(auto-fill, minmax(min(100%, 24rem), 1fr)); }
}
@media (min-width: 48rem) {
	.fg-steps { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.25rem; position: relative; }
	.fg-steps::before {
		content: ""; position: absolute; left: 2.375rem; right: 2.375rem; top: 2.375rem; height: 0.125rem;
		background: repeating-linear-gradient(90deg, var(--fg-moss) 0 0.5rem, transparent 0.5rem 0.875rem);
	}
	.fg-step { padding: 4.25rem 1.25rem 1.5rem; }
	.fg-step__dot { z-index: 1; }
}
@media (min-width: 56rem) {
	.fg-hero__inner { grid-template-columns: minmax(0, 1.35fr) minmax(0, 0.9fr); gap: 3rem; }
	.fg-hero__art { display: block; }
}
@media (min-width: 64rem) {
	.fg-main .wp-block-post-content {
		grid-template-columns: [full-start] minmax(1.5rem, 1fr) [toc-start] 15rem [toc-end] 3rem [main-start] minmax(0, 56rem) [main-end] minmax(1.5rem, 1fr) [full-end];
	}
	.fg-main .wp-block-post-content > .fg-toc { grid-column: toc; grid-row: 2 / span 6; margin-top: 0; }
	.fg-toc__box { position: sticky; top: 6.5rem; }
	.fg-toc__title { cursor: default; pointer-events: none; }
	.fg-toc__title::after { display: none; }
}
@media (min-width: 80rem) {
	.fg-shop__layout { grid-template-columns: 14rem minmax(0, 1fr); align-items: start; }
	.fg-disclosure--rail { position: sticky; top: 6.5rem; padding: 1.25rem; column-gap: 0.75rem; row-gap: 0.75rem; }
	.fg-disclosure--rail::before { grid-row: 1; }
	.fg-disclosure--rail .fg-disclosure__text { grid-column: 1 / -1; font-size: 1rem; }
	.fg-disclosure--closing { position: static; align-self: center; padding: 2rem 1.25rem; }
	.fg-disclosure--closing::before { grid-row: auto; }
	.fg-disclosure--closing .fg-disclosure__text { grid-column: auto; }
	.fg-pairs .fg-card { flex-direction: column; }
	.fg-pairs .fg-window { flex: none; aspect-ratio: 16 / 10; min-height: 0; padding: 0; border-right: 0; border-bottom: 0.0625rem solid var(--fg-line); }
	.fg-pairs { grid-template-columns: repeat(auto-fill, minmax(min(100%, 15.5rem), 1fr)); }
}
